        @Test
        @DisplayName("bhvErrors038 a body truncated after the headers throws NetworkException with status 0")
        fun truncatedBodyAfterHeadersThrowsNetworkExceptionWithStatusZero() {
            val engine =
                MockEngine { _ ->
                    val channel =
                        io.ktor.utils.io
                            .ByteChannel(autoFlush = true)
                    // Part of the body arrives, then the connection is reset before the rest.
                    channel.writeStringUtf8("{\"id\":")
                    channel.cancel(java.io.IOException("connection reset mid-body"))
                    respond(
                        content = channel,
                        status = HttpStatusCode.OK,
                        headers = headersOf("Content-Type", "application/json"),
                    )
                }
            val apiClient = DefaultApiClient(HttpClient(engine) { followRedirects = false })
            val ex =
                assertThrowsExactly(com.example.petstore.errors.NetworkException::class.java) {
                    runBlocking {
                        apiClient.sendRequest("GET", "http://localhost/truncated", emptyMap(), null)
                    }
                }
            assertEquals(0, ex.statusCode)
        }

        @Test
        @DisplayName("bhvErrors043 response-body-read-error-not-wrapped: body-read failure is a NetworkException")
        fun bodyReadFailureWrappedInNetworkException() {
            // Headers are received (status 200) but the body channel is closed
            // with a failure cause, simulating a connection reset / truncated
            // body after the response started. Reading it must surface the
            // SDK's NetworkException, not leak the raw Ktor/IO exception.
            val engine =
                MockEngine { _ ->
                    val channel =
                        io.ktor.utils.io
                            .ByteChannel(autoFlush = true)
                    // cancel(cause) fails the channel with the given throwable so a
                    // reader sees it mid-body; ByteChannel.close() takes no cause arg.
                    channel.cancel(java.io.IOException("simulated body read failure"))
                    respond(
                        content = channel,
                        status = HttpStatusCode.OK,
                        headers = headersOf("Content-Type", "text/plain"),
                    )
                }
            val apiClient = DefaultApiClient(HttpClient(engine) { followRedirects = false })
            val ex =
                assertThrows(com.example.petstore.errors.NetworkException::class.java) {
                    runBlocking {
                        apiClient.sendRequest("GET", "http://localhost/body-fail", emptyMap(), null)
                    }
                }
            assertEquals(0, ex.statusCode)
        }
    }

