            // a NetworkException, and never the body handed back still encoded.
            val engine =
                MockEngine { _ ->
                    respond(
                        content = "payload".toByteArray(Charsets.UTF_8),
                        status = HttpStatusCode.OK,
                        headers = headersOf("Content-Encoding", "made-up-codec"),
                    )
                }
            val apiClient = DefaultApiClient(HttpClient(engine) { followRedirects = false })
            val ex =
                assertThrowsExactly(ApiException::class.java) {
                    runBlocking {
                        apiClient.sendRequest("GET", "http://localhost/unknown-encoding", emptyMap(), null)
