    @Nested
    @DisplayName("ambient proxy selector and per-call timeout against a real socket")
    inner class RealSocket {
        private fun withServer(
            handler: (com.sun.net.httpserver.HttpExchange) -> Unit,
            body: (Int) -> Unit,
        ) {
            val server =
                com.sun.net.httpserver.HttpServer.create(
                    java.net.InetSocketAddress(java.net.InetAddress.getLoopbackAddress(), 0),
                    0,
                )
            server.createContext("/") { exchange ->
                handler(exchange)
                exchange.close()
            }
            server.start()
            try {
                body(server.address.port)
            } finally {
                server.stop(0)
            }
        }

        @Test
        @DisplayName("bhvTransport046 D74 (forced limit): with no TransportOptions.proxy the JVM default ProxySelector is consulted")
        fun ambientProxySelectorIsConsultedWhenNoProxyIsConfigured() {
            val savedSelector = java.net.ProxySelector.getDefault()
            var selectorConsulted = false
            withServer({ exchange ->
                val bytes = "direct".toByteArray()
                exchange.sendResponseHeaders(200, bytes.size.toLong())
                exchange.responseBody.write(bytes)
            }) { port ->
                try {
                    java.net.ProxySelector.setDefault(
                        object : java.net.ProxySelector() {
                            override fun select(uri: java.net.URI?): List<java.net.Proxy> {
                                selectorConsulted = true
                                return listOf(
                                    java.net.Proxy(java.net.Proxy.Type.HTTP, java.net.InetSocketAddress("127.0.0.1", 1)),
                                )
                            }

                            override fun connectFailed(
                                uri: java.net.URI?,
                                sa: java.net.SocketAddress?,
                                ioe: java.io.IOException?,
                            ) {
                                selectorConsulted = true
                            }
                        },
                    )
                    val apiClient = DefaultApiClient(TransportOptions.builder().maxRetries(0).build())
                    // The Ktor CIO engine asks the JVM default ProxySelector when no proxy is configured and
                    // has no way to say "direct" (it rejects Proxy.NO_PROXY), so the other SDKs' rule that
                    // ambient proxy settings are ignored cannot hold here. This pins the behaviour so a Ktor
                    // change that lifts the limit is noticed.
                    assertThrows(
                        com.example.petstore.errors.NetworkException::class.java,
                        { runBlocking { apiClient.sendRequest("GET", "http://127.0.0.1:$port/direct", emptyMap(), null) } },
                    )
                    apiClient.close()
                    assertTrue(selectorConsulted, "the JVM default ProxySelector is expected to be consulted")
                } finally {
                    java.net.ProxySelector.setDefault(savedSelector)
                }
            }
        }

        @Test
        @DisplayName("bhvTransport002 the timeout reaches the transport for this call only")
        fun perCallTimeoutDoesNotPersistToTheNextCall() {
            var requests = 0
            withServer({ exchange ->
                requests++
                if (requests == 1) Thread.sleep(1500)
                val bytes = "ok".toByteArray()
                exchange.sendResponseHeaders(200, bytes.size.toLong())
                exchange.responseBody.write(bytes)
            }) { port ->
                val apiClient =
                    DefaultApiClient(
                        TransportOptions
                            .builder()
                            .timeout(null)
                            .maxRetries(0)
                            .build(),
                    )
                assertThrows(
                    com.example.petstore.errors.NetworkTimeoutException::class.java,
                    {
                        runBlocking {
                            kotlinx.coroutines.withContext(CallSettings(200L, null)) {
                                apiClient.sendRequest("GET", "http://127.0.0.1:$port/slow", emptyMap(), null)
                            }
                        }
                    },
                )
                val response =
                    runBlocking {
                        apiClient.sendRequest("GET", "http://127.0.0.1:$port/next", emptyMap(), null)
                    }
                assertEquals(200, response.statusCode)
                apiClient.close()
            }
        }

        @Test
        @DisplayName("bhvTransport029 a response body that stalls after the headers throws NetworkTimeoutException")
        fun stalledResponseBodyRaisesNetworkTimeoutException() {
            withServer({ exchange ->
                exchange.sendResponseHeaders(200, 0)
                exchange.responseBody.flush()
                Thread.sleep(1500)
            }) { port ->
                val apiClient =
                    DefaultApiClient(
                        TransportOptions
                            .builder()
                            .timeout(null)
                            .maxRetries(0)
                            .build(),
                    )
                assertThrows(
                    com.example.petstore.errors.NetworkTimeoutException::class.java,
                    {
                        runBlocking {
                            kotlinx.coroutines.withContext(CallSettings(300L, null)) {
                                apiClient.sendRequest("GET", "http://127.0.0.1:$port/stall", emptyMap(), null)
                            }
                        }
                    },
                )
                apiClient.close()
            }
        }

        @Test
        @DisplayName("bhvTransport028 F827: a per-call timeout applies even when the client has no timeout of its own")
        fun perCallTimeoutAppliesWithoutAClientTimeout() {
            withServer({ _ -> Thread.sleep(1500) }) { port ->
                val apiClient =
                    DefaultApiClient(
                        TransportOptions
                            .builder()
                            .timeout(null)
                            .maxRetries(0)
                            .build(),
                    )
                val started = System.nanoTime()
                assertThrows(
                    com.example.petstore.errors.NetworkTimeoutException::class.java,
                    {
                        runBlocking {
                            kotlinx.coroutines.withContext(CallSettings(200L, null)) {
                                apiClient.sendRequest("GET", "http://127.0.0.1:$port/slow", emptyMap(), null)
                            }
                        }
                    },
                )
                apiClient.close()
                assertTrue((System.nanoTime() - started) / 1_000_000L < 1400, "the call must give up near its own timeout")
            }
        }
    }

    @Nested
    @DisplayName("close lifecycle")
    inner class CloseLifecycle {
        @Test
        @DisplayName("bhvLifecycle019 close lets an in-flight request finish with its body and refuses a new one")
        fun closeLetsAnInFlightRequestFinishWithItsBody() {
            val engine =
                MockEngine { _ ->
                    kotlinx.coroutines.delay(300)
                    respond(
                        content = "{\"ok\":true}",
                        status = HttpStatusCode.OK,
                        headers = headersOf("Content-Type", "application/json"),
                    )
                }
            val apiClient = DefaultApiClient(io.ktor.client.HttpClient(engine))
            val body =
                runBlocking {
                    val pending =
                        async(kotlinx.coroutines.Dispatchers.Default) {
                            apiClient.sendRequest("GET", "http://localhost/test", emptyMap(), null)
                        }
                    kotlinx.coroutines.delay(100)
                    apiClient.close()
                    assertThrowsExactly(IllegalStateException::class.java) {
                        runBlocking { apiClient.sendRequest("GET", "http://localhost/test", emptyMap(), null) }
                    }
                    pending.await().body
                }
            assertEquals("{\"ok\":true}", body)
        }

        @Test
        @DisplayName("bhvLifecycle037 closing with requests in flight releases the transport once, after the last of them")
        fun bhvLifecycle037ClosingReleasesTheTransportOnceAfterTheLastRequest() {
            val engine =
                MockEngine { _ ->
                    kotlinx.coroutines.delay(300)
                    respond(
                        content = "{}",
                        status = HttpStatusCode.OK,
                        headers = headersOf("Content-Type", "application/json"),
                    )
                }
            val transport = io.ktor.client.HttpClient(engine)
            val apiClient = DefaultApiClient(transport)
            runBlocking {
                val first =
                    kotlinx.coroutines.async(kotlinx.coroutines.Dispatchers.Default) {
                        apiClient.sendRequest("GET", "http://localhost/test", emptyMap(), null)
                    }
                val second =
                    kotlinx.coroutines.async(kotlinx.coroutines.Dispatchers.Default) {
                        apiClient.sendRequest("GET", "http://localhost/test", emptyMap(), null)
                    }
                kotlinx.coroutines.delay(100)
                apiClient.close()
                assertTrue(transport.coroutineContext[kotlinx.coroutines.Job]!!.isActive, "released while requests are in flight")
                first.await()
                second.await()
            }
            assertFalse(
                transport.coroutineContext[kotlinx.coroutines.Job]!!.isActive,
                "the transport was not released after the last request",
            )
            apiClient.close()
            assertFalse(transport.coroutineContext[kotlinx.coroutines.Job]!!.isActive, "a second close reopened the transport")
        }

        @Test
        @DisplayName("bhvLifecycle020 close never closes a transport the caller supplied")
        fun closeNeverClosesACallerSuppliedTransport() {
            val custom = io.ktor.client.HttpClient(MockEngine { respond("{}") })
            val apiClient = DefaultApiClient(TransportOptions.builder().httpClient(custom).build())

            apiClient.close()

            assertTrue(custom.coroutineContext[kotlinx.coroutines.Job]!!.isActive, "a caller-supplied transport was closed")
            custom.close()
        }

        @Test
        @DisplayName("bhvLifecycle023 close-lifecycle-three-way: send after close throws IllegalStateException")
        fun sendAfterCloseThrowsIllegalStateException() {
            // Using a client after close() is a wrong call order: the built-in
            // invalid-state error, not an SDK error.
            val apiClient = DefaultApiClient(mockClient())
            apiClient.close()
            val ex =
                assertThrowsExactly(IllegalStateException::class.java) {
                    runBlocking {
                        apiClient.sendRequest("GET", "http://localhost/test", emptyMap(), null)
                    }
                }
            assertFalse(OpenAPIException::class.java.isInstance(ex), "use-after-close must not be an SDK error")
            assertEquals("ApiClient has been closed and can no longer send requests", ex.message)
        }

        @Test
        @DisplayName("bhvLifecycle021 F1078: close lets a request already in flight finish and releases the transport after the last one")
        fun closeLetsAnInFlightRequestFinishThenReleasesTheTransport() {
            val engine =
                MockEngine { _ ->
                    kotlinx.coroutines.delay(300)
                    respond(
                        content = "{}",
                        status = HttpStatusCode.OK,
                        headers = headersOf("Content-Type", "application/json"),
                    )
                }
            val transport = io.ktor.client.HttpClient(engine)
            val apiClient = DefaultApiClient(transport)
            val result =
                runBlocking {
                    val pending =
                        async(kotlinx.coroutines.Dispatchers.Default) {
                            apiClient.sendRequest("GET", "http://localhost/test", emptyMap(), null)
                        }
                    kotlinx.coroutines.delay(100)
                    apiClient.close()
                    assertTrue(transport.coroutineContext[kotlinx.coroutines.Job]!!.isActive, "released while a request is in flight")
                    val rejected =
                        assertThrowsExactly(IllegalStateException::class.java) {
                            runBlocking { apiClient.sendRequest("GET", "http://localhost/test", emptyMap(), null) }
                        }
                    assertEquals("ApiClient has been closed and can no longer send requests", rejected.message)
                    pending.await()
                }
            assertEquals(200, result.statusCode)
            assertFalse(transport.coroutineContext[kotlinx.coroutines.Job]!!.isActive, "not released after the last request finished")
        }

        @Test
        @DisplayName("bhvLifecycle022 F1078: closing with nothing in flight releases the transport and a second close does nothing")
        fun closeIsIdempotent() {
            val transport = io.ktor.client.HttpClient(MockEngine { respond("{}") })
            val apiClient = DefaultApiClient(transport)

            apiClient.close()
            assertFalse(transport.coroutineContext[kotlinx.coroutines.Job]!!.isActive)
            assertDoesNotThrow { apiClient.close() }
            assertThrowsExactly(IllegalStateException::class.java) {
                runBlocking { apiClient.sendRequest("GET", "http://localhost/test", emptyMap(), null) }
            }
        }
    }

