        @Test
        @DisplayName("withTimeout surfaces TimeoutCancellationException, never ApiException")
        fun withTimeoutIsNotRewrapped() {
            // Structured concurrency: the SDK must not catch and rewrap the
            // coroutine's cancellation signal, so a caller's withTimeout keeps
            // its own exception type.
            val engine =
                MockEngine { _ ->
                    kotlinx.coroutines.delay(5_000)
                    respond("late", HttpStatusCode.OK)
                }
            val apiClient = DefaultApiClient(HttpClient(engine) { followRedirects = false })
            assertThrows(kotlinx.coroutines.TimeoutCancellationException::class.java) {
                runBlocking {
                    kotlinx.coroutines.withTimeout(50) {
                        apiClient.sendRequest("GET", "http://localhost/slow", emptyMap(), null)
                    }
                }
            }
        }

        @Test
        @DisplayName("cancelling the calling job cancels the request without an ApiException")
        fun jobCancellationIsNotRewrapped() {
            val engine =
                MockEngine { _ ->
                    kotlinx.coroutines.delay(5_000)
                    respond("late", HttpStatusCode.OK)
                }
            val apiClient = DefaultApiClient(HttpClient(engine) { followRedirects = false })
            var caught: Throwable? = null
            runBlocking {
                val job =
                    launch {
                        try {
                            apiClient.sendRequest("GET", "http://localhost/slow", emptyMap(), null)
                        } catch (e: Throwable) {
                            caught = e
                            throw e
                        }
                    }
                kotlinx.coroutines.delay(50)
                job.cancel()
                job.join()
            }
            assertInstanceOf(kotlinx.coroutines.CancellationException::class.java, caught)
            assertFalse(caught is ApiException, "cancellation must not be rewrapped, was: $caught")
        }
    }

    @Nested
    @DisplayName("automatic retries")
    inner class AutomaticRetries {
        private val sleeps = mutableListOf<Long>()
        private val seenHeaders = mutableListOf<Headers>()
        private val seenBodies = mutableListOf<String>()
        private var requestCount = 0

        /* Each answer is a status code to respond with or a Throwable to fail with; the last one
         * repeats. The retry pause is recorded in `sleeps` and not waited for. */
        private fun retrying(
            answers: List<Any>,
            maxRetries: Int = 2,
            timeout: Long? = null,
            injectRequestId: Boolean = false,
            retryAfter: String? = null,
            jitter: Double = 0.0,
        ): DefaultApiClient {
            val engine =
                MockEngine { request ->
                    val answer = answers[minOf(requestCount, answers.size - 1)]
                    requestCount++
                    seenHeaders.add(request.headers)
                    seenBodies.add(String(request.body.toByteArray(), Charsets.UTF_8))
                    if (answer is Throwable) {
                        throw answer
                    }
                    respond(
                        content = "{}",
                        status = HttpStatusCode.fromValue(answer as Int),
                        headers =
                            if (retryAfter == null) {
                                headersOf("Content-Type", "application/json")
                            } else {
                                headersOf("Content-Type" to listOf("application/json"), "Retry-After" to listOf(retryAfter))
                            },
                    )
                }
            val httpClient =
                HttpClient(engine) {
                    followRedirects = false
                    install(io.ktor.client.plugins.HttpTimeout)
                }
            val transport =
                TransportOptions
                    .builder()
                    .timeout(timeout)
                    .maxRetries(maxRetries)
                    .injectRequestId(injectRequestId)
                    .build()
            val apiClient = DefaultApiClient(httpClient, transport)
            apiClient.sleeper = { sleeps.add(it) }
            apiClient.jitterSource = { jitter }
            return apiClient
        }

        private fun get(
            apiClient: DefaultApiClient,
            headers: Map<String, String> = emptyMap(),
        ): ApiHttpResponse = runBlocking { apiClient.sendRequest("GET", "http://localhost/items", headers, null) }

        @Test
        @DisplayName("bhvRetries038 a 503 is sent again until it succeeds")
        fun aRetryableStatusIsSentAgain() {
            val apiClient = retrying(listOf(503, 503, 200))

            val response = get(apiClient)

            assertEquals(200, response.statusCode)
            assertEquals(3, requestCount)
            assertEquals(2, sleeps.size)
        }

        @Test
        @DisplayName("bhvRetries024 the last answer is returned once the retries are spent")
        fun theLastAnswerIsReturnedWhenRetriesAreSpent() {
            val apiClient = retrying(listOf(500))

            val response = get(apiClient)

            assertEquals(500, response.statusCode)
            assertEquals(3, requestCount, "the first attempt and two retries")
        }

        @Test
        @DisplayName("bhvRetries018 maxRetries 0 sends the request once")
        fun maxRetriesZeroDisablesRetries() {
            val apiClient = retrying(listOf(503, 200), maxRetries = 0)

            val response = get(apiClient)

            assertEquals(503, response.statusCode)
            assertEquals(1, requestCount)
            assertTrue(sleeps.isEmpty())
        }

        @Test
        @DisplayName("bhvRetries014 maxRetries bounds the number of retries")
        fun maxRetriesBoundsTheNumberOfRetries() {
            val apiClient = retrying(listOf(503), maxRetries = 4)

            get(apiClient)

            assertEquals(5, requestCount)
            assertEquals(4, sleeps.size)
        }

        @Test
        @DisplayName("bhvRetries021 retries exactly 408, 409, 429 and every 5xx but 501, and no other status")
        fun retryableStatusesAreRetried() {
            for (status in listOf(408, 409, 429, 500, 502, 503, 504, 599)) {
                requestCount = 0
                get(retrying(listOf(status), maxRetries = 1))
                assertEquals(2, requestCount, "status $status must be retried once")
            }
            for (status in listOf(200, 201, 301, 400, 401, 403, 404, 422, 501)) {
                requestCount = 0
                get(retrying(listOf(status)))
                assertEquals(1, requestCount, "status $status must not be retried")
            }
        }

        @Test
        @DisplayName("bhvRetries013 a network error before a response is retried")
        fun aNetworkErrorIsRetried() {
            val apiClient = retrying(listOf(java.io.IOException("connection reset"), 200))

            val response = get(apiClient)

            assertEquals(200, response.statusCode)
            assertEquals(2, requestCount)
        }

        @Test
        @DisplayName("a network error that persists is reported after the retries")
        fun aPersistentNetworkErrorIsReported() {
            val apiClient = retrying(listOf(java.io.IOException("connection reset")))

            assertThrowsExactly(com.example.petstore.errors.NetworkException::class.java) { get(apiClient) }

            assertEquals(3, requestCount)
        }

        @Test
        @DisplayName("bhvRetries033 the last network error is reported once the retries are spent")
        fun theLastNetworkErrorIsReportedOnceTheRetriesAreSpent() {
            val apiClient = retrying(listOf(java.io.IOException("first"), java.io.IOException("second")))

            val ex = assertThrowsExactly(com.example.petstore.errors.NetworkException::class.java) { get(apiClient) }

            assertEquals(3, requestCount)
            assertEquals("second", ex.cause?.message)
        }

        @Test
        @DisplayName("bhvRetries042 a timeout is not retried")
        fun aTimeoutIsNotRetried() {
            val apiClient = retrying(listOf(java.net.SocketTimeoutException("socket timed out")))

            assertThrowsExactly(com.example.petstore.errors.NetworkTimeoutException::class.java) { get(apiClient) }

            assertEquals(1, requestCount)
        }

        @Test
        @DisplayName("bhvRetries027 backoff doubles from half a second to eight seconds with quarter jitter")
        fun backoffDoublesUpToEightSecondsWithQuarterJitter() {
            val apiClient = retrying(listOf(503), maxRetries = 6, jitter = 0.0)

            get(apiClient)

            assertEquals(listOf(500L, 1000L, 2000L, 4000L, 8000L, 8000L), sleeps)

            sleeps.clear()
            requestCount = 0
            val shortest = retrying(listOf(503), maxRetries = 1, jitter = 0.999999)
            get(shortest)
            assertEquals(1, sleeps.size)
            assertTrue(sleeps[0] in 375L..376L, "the shortest wait is 75% of 500 ms, got ${sleeps[0]}")
        }

        @Test
        @DisplayName("bhvRetries030 the retry backoff jitter takes at most a quarter off the delay")
        fun jitterTakesAtMostAQuarterOffTheDelay() {
            for (jitter in listOf(0.0, 0.5, 0.999999)) {
                sleeps.clear()
                requestCount = 0
                get(retrying(listOf(503), maxRetries = 1, jitter = jitter))

                assertEquals(1, sleeps.size, "one retry for jitter $jitter")
                assertTrue(sleeps[0] in 375L..500L, "jitter $jitter must leave 375 to 500 ms, got ${sleeps[0]}")
            }
        }

        @Test
        @DisplayName("bhvRetries041 the backoff starts at 0.5 s, doubles up to 8 s and has up to 25% jitter taken off")
        fun backoffStartsAtHalfASecondAndHasUpToAQuarterTakenOff() {
            val apiClient = retrying(listOf(503), maxRetries = 5, jitter = 0.0)

            get(apiClient)

            assertEquals(listOf(500L, 1000L, 2000L, 4000L, 8000L), sleeps)

            sleeps.clear()
            requestCount = 0
            get(retrying(listOf(503), maxRetries = 1, jitter = 0.999999))
            assertTrue(sleeps[0] in 375L..376L, "the shortest first wait is 75% of 500 ms, got ${sleeps[0]}")
        }

        @Test
        @DisplayName("bhvRetries026 Retry-After in seconds replaces the backoff")
        fun retryAfterSecondsIsHonoured() {
            val apiClient = retrying(listOf(429, 200), retryAfter = "2")

            get(apiClient)

            assertEquals(listOf(2000L), sleeps)
        }

        @Test
        @DisplayName("bhvRetries029 falls back to the backoff when Retry-After is not understood")
        fun unreadableRetryAfterFallsBackToTheBackoff() {
            val apiClient = retrying(listOf(503, 200), retryAfter = "soon")

            get(apiClient)

            assertEquals(listOf(500L), sleeps)
        }

        @Test
        @DisplayName("bhvRetries023 Retry-After is capped at 60 seconds")
        fun retryAfterIsCappedAtSixtySeconds() {
            val apiClient = retrying(listOf(503, 200), retryAfter = "3600")

            get(apiClient)

            assertEquals(listOf(60_000L), sleeps)
        }

        @Test
        @DisplayName("bhvRetries022 Retry-After accepts an HTTP date and ignores one that is malformed")
        fun retryAfterParsing() {
            val now = java.time.Instant.parse("2030-01-01T00:00:00Z")
            assertEquals(
                10_000L,
                RetryPolicy.parseRetryAfter("Tue, 01 Jan 2030 00:00:10 GMT", now),
            )
            assertEquals(0L, RetryPolicy.parseRetryAfter("Mon, 31 Dec 2029 23:59:00 GMT", now))
            assertEquals(60_000L, RetryPolicy.parseRetryAfter("Tue, 01 Jan 2030 01:00:00 GMT", now))
            assertEquals(1500L, RetryPolicy.parseRetryAfter(" 1.5 ", now))
            assertNull(RetryPolicy.parseRetryAfter("soon", now))
            assertNull(RetryPolicy.parseRetryAfter("-5", now))
            assertNull(RetryPolicy.parseRetryAfter("", now))
            assertNull(RetryPolicy.parseRetryAfter(null, now))
            assertEquals(500L, RetryPolicy.delayMillis(0, "soon", 0.0, now))
        }

        @Test
        @DisplayName("bhvRetries025 the retries never extend the end-to-end timeout")
        fun retriesStayInsideTheTimeoutBudget() {
            val apiClient = retrying(listOf(503, 200), timeout = 1000L, retryAfter = "5")

            val response = get(apiClient)

            assertEquals(503, response.statusCode, "a 5 s wait cannot fit in a 1 s budget")
            assertEquals(1, requestCount)
            assertTrue(sleeps.isEmpty())
        }

        @Test
        @DisplayName("bhvRetries019 each call starts a fresh timeout budget, so a retry that fits one call fits the next")
        fun timeoutBudgetStartsAfreshForEveryCall() {
            // Each call's 1 s budget is spent to 600 ms by its own wait. A budget shared across
            // calls would have 400 ms left for the second call and stop its retry.
            val apiClient = retrying(listOf(503, 200, 503, 200), timeout = 1000L, retryAfter = "0.6")
            apiClient.sleeper = { kotlinx.coroutines.delay(it) }

            assertEquals(200, get(apiClient).statusCode)
            assertEquals(200, get(apiClient).statusCode)
            assertEquals(4, requestCount)
        }

        @Test
        @DisplayName("a retry whose wait fits in the timeout budget is sent")
        fun aWaitThatFitsTheBudgetIsTaken() {
            val apiClient = retrying(listOf(503, 200), timeout = 60_000L)

            val response = get(apiClient)

            assertEquals(200, response.statusCode)
            assertEquals(2, requestCount)
        }

        @Test
        @DisplayName("bhvRetries028 cancelling the caller during the wait stops the retrying")
        fun cancellationStopsTheRetrying() {
            val apiClient = retrying(listOf(503), retryAfter = "30")
            apiClient.sleeper = { kotlinx.coroutines.delay(it) }
            var caught: Throwable? = null
            runBlocking {
                val job =
                    launch {
                        try {
                            apiClient.sendRequest("GET", "http://localhost/items", emptyMap(), null)
                        } catch (e: Throwable) {
                            caught = e
                            throw e
                        }
                    }
                while (requestCount == 0) {
                    kotlinx.coroutines.delay(10)
                }
                kotlinx.coroutines.delay(50)
                job.cancel()
                job.join()
            }
            assertInstanceOf(kotlinx.coroutines.CancellationException::class.java, caught)
            assertEquals(1, requestCount)
        }

        @Test
        @DisplayName("bhvRetries039 every retry is a fresh request that carries the same authentication headers again")
        fun everyRetryIsAFreshRequest() {
            val apiClient = retrying(listOf(503, 503, 200), injectRequestId = true)

            get(apiClient, mapOf("Authorization" to "Bearer t", "X-Custom" to "v"))

            assertEquals(3, seenHeaders.size)
            for (headers in seenHeaders) {
                assertEquals("Bearer t", headers["Authorization"])
                assertEquals("v", headers["X-Custom"])
            }
            assertEquals(3, seenHeaders.map { it["X-Request-ID"] }.toSet().size, "a new request id each time")
        }

        @Test
        @DisplayName("bhvRetries034 a string body is sent again unchanged on every retry")
        fun aBodyIsReplayed() {
            val apiClient = retrying(listOf(503, 200))

            runBlocking {
                apiClient.sendRequest(
                    "POST",
                    "http://localhost/items",
                    mapOf("Content-Type" to "application/json"),
                    "{\"a\":1}",
                )
            }

            assertEquals(listOf("{\"a\":1}", "{\"a\":1}"), seenBodies)
        }
    }

    @Nested
    @DisplayName("wire transport behaviours")
    inner class WireTransportBehaviours {
        @Test
        @DisplayName("bhvTransport067 a successful response with no body is returned as a success with an empty body")
        fun successWithNoBodyIsReturnedAsSuccess() {
            val apiClient =
                DefaultApiClient(mockClient(statusCode = HttpStatusCode.NoContent, body = ""), TransportOptions.builder().build())
            val response = runBlocking { apiClient.sendRequest("DELETE", "http://localhost/test", emptyMap(), null) }
            assertEquals(204, response.statusCode)
            assertEquals("", response.body)
        }

        @Test
        @DisplayName("bhvTransport068 a call made after its cancellation has already happened sends no request")
        fun cancelledCallSendsNoRequest() {
            var requests = 0
            val engine =
                MockEngine { _ ->
                    requests++
                    respond(content = "{}", status = HttpStatusCode.OK)
                }
            val apiClient = DefaultApiClient(HttpClient(engine), TransportOptions.builder().build())
            assertThrows(kotlinx.coroutines.CancellationException::class.java) {
                runBlocking {
                    this.coroutineContext[kotlinx.coroutines.Job]!!.cancel()
                    apiClient.sendRequest("GET", "http://localhost/test", emptyMap(), null)
                }
            }
            assertEquals(0, requests)
        }

        @Test
        @DisplayName("bhvTransport071 a single configured timeout applies to every timed phase of a request")
        fun singleTimeoutAppliesToEveryTimedPhase() {
            var requestMs: Long? = null
            var connectMs: Long? = null
            var socketMs: Long? = null
            val client =
                mockClient(requestCapture = { req ->
                    val armed = req.getCapabilityOrNull(io.ktor.client.plugins.HttpTimeoutCapability)!!
                    requestMs = armed.requestTimeoutMillis
                    connectMs = armed.connectTimeoutMillis
                    socketMs = armed.socketTimeoutMillis
                })
            val apiClient = DefaultApiClient(client, TransportOptions.builder().timeout(5000L).build())
            runBlocking { apiClient.sendRequest("GET", "http://localhost/test", emptyMap(), null) }
            assertEquals(5000L, requestMs)
            assertEquals(5000L, connectMs)
            assertEquals(5000L, socketMs)
        }

        @Test
        @DisplayName("bhvTransport072 a deadline that expires while connecting raises the timeout error, an unrelated failure does not")
        fun expiredDeadlineRaisesTimeoutAndUnrelatedFailureDoesNot() {
            val timeoutEngine =
                MockEngine { _ ->
                    throw io.ktor.client.plugins
                        .HttpRequestTimeoutException("http://localhost/test", 100L)
                }
            val timeoutApi = DefaultApiClient(HttpClient(timeoutEngine), TransportOptions.builder().maxRetries(0).build())
            assertThrows(com.example.petstore.errors.NetworkTimeoutException::class.java) {
                runBlocking { timeoutApi.sendRequest("GET", "http://localhost/test", emptyMap(), null) }
            }
            val refusedEngine = MockEngine { _ -> throw java.net.ConnectException("refused") }
            val refusedApi = DefaultApiClient(HttpClient(refusedEngine), TransportOptions.builder().maxRetries(0).build())
            val ex =
                assertThrows(com.example.petstore.errors.NetworkException::class.java) {
                    runBlocking { refusedApi.sendRequest("GET", "http://localhost/test", emptyMap(), null) }
                }
            assertFalse(ex is com.example.petstore.errors.NetworkTimeoutException)
        }

        @Test
        @DisplayName("bhvTransport073 a response that claims a compression encoding but holds a corrupt stream raises the API error")
        fun corruptCompressedBodyRaisesTheApiError() {
            val engine =
                MockEngine { _ ->
                    respond(
                        content = "not gzip data",
                        status = HttpStatusCode.OK,
                        headers = headersOf("Content-Type", "application/json", "Content-Encoding", "gzip"),
                    )
                }
            val apiClient = DefaultApiClient(HttpClient(engine), TransportOptions.builder().build())
            val ex =
                assertThrowsExactly(com.example.petstore.errors.ApiException::class.java) {
                    runBlocking { apiClient.sendRequest("GET", "http://localhost/test", emptyMap(), null) }
                }
            assertTrue(ex.message!!.startsWith("Failed to decompress gzip response body"), ex.message)
        }

        @Test
        @DisplayName("bhvTransport077 a CA certificate path that names a directory fails when the client is built, naming that path")
        fun caPathNamingADirectoryFailsWhenBuilt() {
            val dir =
                java.nio.file.Files
                    .createTempDirectory("ca-dir")
                    .toString()
            val transport = TransportOptions.builder().caCertPath(dir).build()
            val ex =
                assertThrows(IllegalArgumentException::class.java) {
                    DefaultApiClient(transport)
                }
            assertTrue(ex.message!!.contains(dir), ex.message)
        }

        @Test
        @DisplayName("bhvTransport078 a caller-supplied HTTP client is refused at construction when a proxy setting is also configured")
        fun suppliedClientWithProxyIsRefused() {
            val ex =
                assertThrows(IllegalArgumentException::class.java) {
                    TransportOptions
                        .builder()
                        .httpClient(mockClient())
                        .proxy("http://proxy.example.com:3128")
                        .build()
                }
            assertTrue(ex.message!!.startsWith("A custom httpClient cannot be combined"), ex.message)
        }

        @Test
        @DisplayName("bhvTransport079 turning off certificate verification with a supplied client is refused at construction")
        fun disabledVerificationWithSuppliedClientIsRefused() {
            assertThrows(IllegalArgumentException::class.java) {
                TransportOptions
                    .builder()
                    .httpClient(mockClient())
                    .verifySsl(false)
                    .build()
            }
        }

        @Test
        @DisplayName("bhvTransport080 a proxy setting that is not a URL makes construction fail rather than being dropped")
        fun unusableProxySettingFailsConstruction() {
            assertThrows(IllegalArgumentException::class.java) {
                TransportOptions.builder().proxy("not a url").build()
            }
        }

        @Test
        @DisplayName("bhvTransport081 a caller-supplied HTTP client carries every request with the URL and caller headers unchanged")
        fun suppliedClientCarriesEveryRequestUnchanged() {
            var captured: io.ktor.client.request.HttpRequestData? = null
            var count = 0
            val client =
                mockClient(requestCapture = { req ->
                    count++
                    captured = req
                })
            val apiClient = DefaultApiClient(client, TransportOptions.builder().build())
            runBlocking {
                apiClient.sendRequest("GET", "http://localhost/test", mapOf("X-Caller" to "yes"), null)
            }
            assertEquals(1, count)
            assertEquals("http://localhost/test", captured!!.url.toString())
            assertEquals("yes", captured!!.headers["X-Caller"])
        }

        @Test
        @DisplayName("bhvTransport082 a request made with only a timeout configured completes and returns its response")
        fun requestWithOnlyATimeoutCompletes() {
            val apiClient = DefaultApiClient(mockClient(), TransportOptions.builder().timeout(1000L).build())
            val response = runBlocking { apiClient.sendRequest("GET", "http://localhost/test", emptyMap(), null) }
            assertEquals(200, response.statusCode)
        }
    }

    @Nested
    @DisplayName("wire redirect behaviours")
    inner class WireRedirectBehaviours {
        private fun redirectThenOk(
            status: HttpStatusCode,
            seen: MutableList<io.ktor.client.request.HttpRequestData>,
        ): MockEngine =
            MockEngine { req ->
                seen.add(req)
                if (seen.size == 1) {
                    respond(content = "", status = status, headers = headersOf("Location", "http://localhost/b"))
                } else {
                    respond(content = "{}", status = HttpStatusCode.OK, headers = headersOf("Content-Type", "application/json"))
                }
            }

        @Test
        @DisplayName("bhvRedirects038 a 307 redirect that keeps the method resends the original body and its content type")
        fun temporaryRedirectResendsBodyAndType() {
            val seen = mutableListOf<io.ktor.client.request.HttpRequestData>()
            val apiClient =
                DefaultApiClient(
                    HttpClient(redirectThenOk(HttpStatusCode.TemporaryRedirect, seen)),
                    TransportOptions.builder().build(),
                )
            runBlocking {
                apiClient.sendRequest("POST", "http://localhost/a", mapOf("Content-Type" to "text/plain"), "payload")
            }
            assertEquals(2, seen.size)
            assertEquals(io.ktor.http.HttpMethod.Post, seen[1].method)
            assertEquals("text/plain", seen[1].headers["Content-Type"])
        }

        @Test
        @DisplayName("bhvRedirects040 a 302 redirect from HTTPS to plain HTTP is followed for a request that sends no body")
        fun foundRedirectFromHttpsToHttpIsFollowed() {
            val seen = mutableListOf<io.ktor.client.request.HttpRequestData>()
            val apiClient =
                DefaultApiClient(
                    HttpClient(redirectThenOk(HttpStatusCode.Found, seen)),
                    TransportOptions.builder().build(),
                )
            val response =
                runBlocking {
                    apiClient.sendRequest("GET", "https://localhost/a", emptyMap(), null)
                }
            assertEquals(200, response.statusCode)
            assertEquals("http://localhost/b", seen[1].url.toString())
        }

        @Test
        @DisplayName("bhvRedirects041 a redirect that turns a POST into a GET sends no Content-Length or Content-Type")
        fun postTurnedIntoGetSendsNoBodyHeaders() {
            val seen = mutableListOf<io.ktor.client.request.HttpRequestData>()
            val apiClient =
                DefaultApiClient(
                    HttpClient(redirectThenOk(HttpStatusCode.SeeOther, seen)),
                    TransportOptions.builder().build(),
                )
            runBlocking {
                apiClient.sendRequest("POST", "http://localhost/a", mapOf("Content-Type" to "text/plain"), "payload")
            }
            assertEquals(io.ktor.http.HttpMethod.Get, seen[1].method)
            assertNull(seen[1].headers["Content-Length"])
            assertNull(seen[1].headers["Content-Type"])
        }

        @Test
        @DisplayName("bhvRedirects042 a 307 redirect of a bodyless POST keeps the request a POST")
        fun temporaryRedirectKeepsBodylessPost() {
            val seen = mutableListOf<io.ktor.client.request.HttpRequestData>()
            val apiClient =
                DefaultApiClient(
                    HttpClient(redirectThenOk(HttpStatusCode.TemporaryRedirect, seen)),
                    TransportOptions.builder().build(),
                )
            runBlocking { apiClient.sendRequest("POST", "http://localhost/a", emptyMap(), null) }
            assertEquals(io.ktor.http.HttpMethod.Post, seen[1].method)
        }
    }

    @Test
    @DisplayName("bhvRetries043 an unauthorized response is returned to the caller after one request when no authenticator can refresh")
    fun unauthorizedIsNotReplayedWithoutFreshCredentials() {
        var requests = 0
        val client =
            mockClient(
                statusCode = HttpStatusCode.Unauthorized,
                requestCapture = { requests++ },
            )
        val apiClient = DefaultApiClient(client, TransportOptions.builder().maxRetries(3).build())
        assertThrows(com.example.petstore.errors.UnauthorizedException::class.java) {
            runBlocking { apiClient.sendRequest("GET", "http://localhost/test", emptyMap(), null) }
        }
        assertEquals(1, requests)
    }

    @Test
    @DisplayName("bhvLifecycle036 closing a client a second time raises no error and releases nothing further")
    fun closingTwiceRaisesNoError() {
        val apiClient = DefaultApiClient(mockClient(), TransportOptions.builder().build())
        apiClient.close()
        assertDoesNotThrow { apiClient.close() }
    }
